        if (email == null || email.isEmpty()) {
            owner.setEmail(null);
            return true;
        }
        if (!EMAIL_PATTERN.matcher(email).matches()) {
            return false;
        }
        owner.setEmail(email.toLowerCase(java.util.Locale.ROOT));
